import json

def get_q1():
    with open('/root/DATA/products/CoachForce.json', 'r') as f:
        data = json.load(f)

    print("Documents containing 'Market Research Report':")
    doc_ids = []
    for doc in data.get('documents', []):
        if 'market research report' in doc.get('type', '').lower() or 'market research report' in doc.get('content', '').lower() or 'market research report' in str(doc.get('document_link', '')).lower() or 'coachforce' in doc.get('content', '').lower():
            doc_id = doc.get('id')
            if 'market research' in doc.get('type', '').lower():
                doc_ids.append(doc_id)
            print(f"Doc ID: {doc_id} - Date: {doc.get('date')} - Type: {doc.get('type')} - Author: {doc.get('author')}")

    print("\nSlack messages about market research report:")
    for msg in data.get('slack', []):
        text = msg.get('Message', '')
        if isinstance(text, dict):
            text = json.dumps(text)

        if 'market research' in text.lower() or any(doc_id in text for doc_id in doc_ids):
            print(f"Msg ID: {msg.get('id')} - Channel: {msg.get('Channel')} - Sender: {msg.get('sender')}")
            print(f"  Text: {text[:150]}...")
            if 'ThreadReplies' in msg:
                print(f"  Replies: {len(msg['ThreadReplies'])}")
                for reply in msg['ThreadReplies']:
                    print(f"    Reply from {reply.get('sender', 'unknown')}: {str(reply.get('Message', ''))[:100]}")

    print("\nMeeting transcripts:")
    for m in data.get('meeting_transcripts', []):
        if 'market research' in m.get('document_type', '').lower() or 'market research' in m.get('transcript', '').lower():
            print(f"Meeting ID: {m.get('id')} - Type: {m.get('document_type')}")

    print("\nMeeting chats:")
    for c in data.get('meeting_chats', []):
        # We need to print out relevant messages
        for msg in c.get('messages', []):
            text = msg.get('text', '')
            if 'market research' in text.lower() or any(doc_id in text for doc_id in doc_ids):
                print(f"Chat in Meeting {c.get('meeting_id', '')} - Sender {msg.get('sender')}: {text[:100]}")

get_q1()
