    doc_ids = []
    for doc in data.get('documents', []):
        if 'market research report' in doc.get('type', '').lower() or 'market research report' in doc.get('content', '').lower() or 'market research report' in str(doc.get('document_link', '')).lower() or 'coachforce' in doc.get('content', '').lower():
            doc_id = doc.get('id')
            if 'market research' in doc.get('type', '').lower():
                doc_ids.append(doc_id)
            print(f"Doc ID: {doc_id} - Date: {doc.get('date')} - Type: {doc.get('type')} - Author: {doc.get('author')}")

    print("\nSlack messages about market research report:")
    for msg in data.get('slack', []):
        text = msg.get('Message', '')
        if isinstance(text, dict):
            text = json.dumps(text)

        if 'market research' in text.lower() or any(doc_id in text for doc_id in doc_ids):
            print(f"Msg ID: {msg.get('id')} - Channel: {msg.get('Channel')} - Sender: {msg.get('sender')}")
